function insRow1()
{
var description = new Array();
description[0] = "<tbody><tr><td><p>Adem&aacute;s de las fiestas establecidas en este inciso, debe tenerse en cuenta que el art&iacute;culo <A href='ley_2578_2026.html#6' >6</A> de la Ley 2578 de 2026, 'por medio de la cual se vincula a la Naci&oacute;n en el homenaje al municipio de Chiquinquir&aacute; en el departamento de Boyac&aacute;, como destacado Centro Tur&iacute;stico Religioso, Hist&oacute;rico y Cultural, y se dictan otras disposiciones', publicada en el Diario Oficial No. 53.510 de 2 de junio de 2026, estableci&oacute;: </p><p><span class='i_aj'>'ART&Iacute;CULO <A href='ley_2578_2026.html#6' >6</A>o. FIESTA NACIONAL. &#160;Decl&aacute;rase el D&iacute;a de Nuestra Se&ntilde;ora del Rosario de Chiquinquir&aacute;, que se conmemora el 9 de julio de cada a&ntilde;o, como d&iacute;a festivo de car&aacute;cter nacional, de obligatorio cumplimiento en todo el territorio de la Rep&uacute;blica de Colombia. Por consiguiente, todos los trabajadores, tanto del sector p&uacute;blico como del sector privado, tienen derecho al descanso remunerado por la celebraci&oacute;n de car&aacute;cter religioso. Se aplicar&aacute;n las disposiciones de la ley 51 de 1983 para efectos de determinar el d&iacute;a en el cual se disfrute del descanso remunerado en el calendario.'. </span></p> </td></tr></tbody>";
var z=document.getElementById('Table1').rows[0];
if (z==null) {
              var x=document.getElementById('Table1').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table1').deleteRow(0)
             }
}
